from copy import deepcopy
from random import Random
import sqlite3
from unittest.mock import patch

import solution
from ledger_db import open_ledger

opening = {\"a\": 5, \"b\": 0, \"\": 1, \"\\ud800\": (1 << 64)}
transfers = [
    [\"retry\", \"a\", \"missing\", 9],
    [\"retry\", \"a\", \"b\", 9],
    [\"retry\", \"a\", \"b\", 2],
    [\"retry\", \"missing\", \"missing\", 9],
    [\"self\", \"b\", \"b\", 3],
    [\"self\", \"b\", \"b\", 2],
    [\"self\", \"a\", \"b\", 1],
    [{\"x\": [1]}, \"\\ud800\", \"\", 1 << 64],
    [{\"x\": [1]}, \"\", \"a\", 1],
    [7, \"\", \"a\", 1 << 64],
    [\"7\", \"a\", \"\", (1 << 64) + 1],
    [None, \"a\", \"b\", 1],
    [None, \"b\", \"a\", 1],
]
original = deepcopy((opening, transfers))
assert solution.post(opening, iter(transfers)) == {
    \"balances\": {\"a\": 1, \"b\": 3, \"\": (1 << 64) + 2, \"\\ud800\": 0},
    \"statuses\": [
        \"unknown\", \"insufficient\", \"posted\", \"duplicate\", \"insufficient\",
        \"posted\", \"duplicate\", \"posted\", \"duplicate\", \"posted\", \"posted\",
        \"posted\", \"duplicate\",
    ],
}
assert (opening, transfers) == original
assert solution.post({}, []) == {\"balances\": {}, \"statuses\": []}

def reference(opening, transfers):
    balances = opening.copy()
    statuses = []
    applied = []
    for transfer_id, source, target, amount in transfers:
        if transfer_id in applied:
            status = \"duplicate\"
        elif source not in balances or target not in balances:
            status = \"unknown\"
        elif balances[source] < amount:
            status = \"insufficient\"
        else:
            balances[source] -= amount
            balances[target] += amount
            applied.append(transfer_id)
            status = \"posted\"
        statuses.append(status)
    return {\"balances\": balances, \"statuses\": statuses}

random = Random(31)
accounts = [\"a\", \"b\", \"\", \"\\ud800\", \"x\\0y\"]
ids = [\"a\", 1, \"1\", None, [\"nested\"], {\"x\": [1]}, frozenset({1}), {1}]
amounts = [1, 2, 7, (1 << 63) - 1, 1 << 63, 1 << 64, 1 << 15000]
for _ in range(200):
    opening = {name: random.choice([0, *amounts]) for name in random.sample(accounts, random.randrange(len(accounts) + 1))}
    transfers = [
        [random.choice(ids), random.choice(accounts), random.choice(accounts), random.choice(amounts)]
        for _ in range(40)
    ]
    assert solution.post(opening, transfers) == reference(opening, transfers)

class InspectOnClose:
    def __init__(self, opening):
        self.connection = open_ledger(opening)
        self.connection.execute(\"\"\"
            CREATE TRIGGER fail_second BEFORE INSERT ON applied_transfers
            WHEN NEW.id = 1
            BEGIN
                SELECT RAISE(ABORT, 'simulated write failure');
            END
        \"\"\")

    def __enter__(self):
        return self.connection.__enter__()

    def __exit__(self, *args):
        return self.connection.__exit__(*args)

    def __getattr__(self, name):
        return getattr(self.connection, name)

    def close(self):
        self.balances = dict(self.connection.execute(\"SELECT name, balance FROM accounts\"))
        self.applied = self.connection.execute(\"SELECT id FROM applied_transfers\").fetchall()
        self.connection.close()

connection = InspectOnClose({\"a\": 10, \"b\": 0})
with patch.object(solution, \"open_ledger\", return_value=connection):
    try:
        solution.post({\"a\": 10, \"b\": 0}, [[\"first\", \"a\", \"b\", 2], [\"second\", \"a\", \"b\", 3]])
    except sqlite3.IntegrityError as error:
        assert str(error) == \"simulated write failure\"
    else:
        raise AssertionError(\"the injected error did not reach the caller\")
assert connection.balances == {\"a\": 8, \"b\": 2}
assert connection.applied == [(0,)]
print(\"Edge cases, 200 randomized comparisons and transaction rollback passed.\")
